CREATE OR REPLACE FUNCTION public.is_approved_brand_application(_application_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.brand_applications WHERE id = _application_id AND status = 'approved') $$;
GRANT EXECUTE ON FUNCTION public.is_approved_brand_application(uuid) TO anon, authenticated, service_role;
DROP POLICY "Public can view published products from approved brands" ON public.brand_products;
CREATE POLICY "Public can view published products from approved brands" ON public.brand_products FOR SELECT TO anon, authenticated USING (status = 'published' AND public.is_approved_brand_application(brand_application_id));
CREATE POLICY "Brands can view their own product photos" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'brand-product-images' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Shoppers can view published product photos" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'brand-product-images' AND EXISTS (SELECT 1 FROM public.brand_products p WHERE p.image_path = name AND p.status = 'published' AND public.is_approved_brand_application(p.brand_application_id)));
CREATE POLICY "Brands can upload their own product photos" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'brand-product-images' AND (storage.foldername(name))[1] = auth.uid()::text AND EXISTS (SELECT 1 FROM public.brand_applications a WHERE a.user_id = auth.uid() AND a.status = 'approved'));
CREATE POLICY "Brands can update their own product photos" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'brand-product-images' AND (storage.foldername(name))[1] = auth.uid()::text) WITH CHECK (bucket_id = 'brand-product-images' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Brands can remove their own product photos" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'brand-product-images' AND (storage.foldername(name))[1] = auth.uid()::text);